parameters.text:
=You are a professional sales follow-up message generator for WebGrowth Solutions.

Generate a short, personalized follow-up message for the lead.

Use ONLY the information provided in the input.
Do not invent services, prices, deadlines, features, or promises.

The message should:
- Address the lead by name.
- Mention their business.
- Mention the service they are interested in.
- Briefly acknowledge their requirement.
- Match the lead's qualification level.
- Have a professional but friendly tone.
- End with a simple call to action.
- Be suitable for WhatsApp or email.
- Do not mention the internal score or classification.

Lead information:

Name: {{ $json.lead_name }}
Business:{{ $json.business }}
Service: {{ $json.service }}
Requirement: {{ $json.requirement }}
Budget: {{ $json.budget }}
Timeline: {{ $json.timeline }}
Classification: {{ $json.classification }}

parameters.jsCode:
const results = [];

for (const item of $input.all()) {

  // Structured Output Parser puts lead data inside "output"
  const lead = item.json.output;

  let budgetScore = 0;
  let clarityScore = 0;
  let timelineScore = 0;
  let businessFitScore = 0;
  let serviceFitScore = 0;
  let decisionMakerScore = 0;


  // =========================
  // BUDGET SCORE - 30 POINTS
  // =========================

  switch (lead.budget_category) {

    case "High-value":
      budgetScore = 30;
      break;

    case "Qualified":
      budgetScore = 25;
      break;

    case "Medium":
      budgetScore = 15;
      break;

    case "Low":
      budgetScore = 5;
      break;

    default:
      budgetScore = 0;
  }


  // ================================
  // REQUIREMENT CLARITY - 25 POINTS
  // ================================

  switch (lead.requirement_clarity) {

    case "High":
      clarityScore = 25;
      break;

    case "Medium":
      clarityScore = 15;
      break;

    case "Low":
      clarityScore = 5;
      break;

    case "Unknown":
      clarityScore = 0;
      break;

    default:
      clarityScore = 0;
  }


  // =========================
  // TIMELINE SCORE - 20 POINTS
  // =========================

  switch (lead.timeline_category) {

    case "Good":
      timelineScore = 20;
      break;

    case "Urgent":
      timelineScore = 15;
      break;

    case "Long-term":
      timelineScore = 5;
      break;

    default:
      timelineScore = 0;
  }


  // =========================
  // BUSINESS FIT - 10 POINTS
  // =========================

  if (lead.business_fit === true) {
    businessFitScore = 10;
  }


  // =========================
  // SERVICE FIT - 10 POINTS
  // =========================

  if (lead.service_fit === true) {
    serviceFitScore = 10;
  }


  // =========================
  // DECISION MAKER - 5 POINTS
  // =========================

  if (lead.decision_maker === true) {
    decisionMakerScore = 5;
  }


  // =========================
  // TOTAL SCORE
  // =========================

  const totalScore =
    budgetScore +
    clarityScore +
    timelineScore +
    businessFitScore +
    serviceFitScore +
    decisionMakerScore;


  // =========================
  // CLASSIFICATION
  // =========================

  let classification;


  // -----------------------------------------
  // RULE 1: CLEARLY UNQUALIFIED LEADS
  // -----------------------------------------

  if (
    lead.business_fit === false ||
    lead.service_fit === false ||
    lead.budget_category === "Low"
  ) {

    classification = "UNQUALIFIED";

  }


  // -----------------------------------------
  // RULE 2: HOT LEAD
  // -----------------------------------------
  // HOT requires:
  // - Very strong score
  // - Qualified or High-value budget
  // -----------------------------------------

  else if (
    totalScore >= 85 &&
    (
      lead.budget_category === "Qualified" ||
      lead.budget_category === "High-value"
    )
  ) {

    classification = "HOT";

  }


  // -----------------------------------------
  // RULE 3: WARM LEAD
  // -----------------------------------------

  else if (totalScore >= 65) {

    classification = "WARM";

  }


  // -----------------------------------------
  // RULE 4: COLD LEAD
  // -----------------------------------------

  else if (totalScore >= 40) {

    classification = "COLD";

  }


  // -----------------------------------------
  // RULE 5: UNQUALIFIED
  // -----------------------------------------

  else {

    classification = "UNQUALIFIED";

  }


  // =========================
  // FINAL OUTPUT
  // =========================

  results.push({

    json: {

      ...lead,

      scoring: {

        budget_score: budgetScore,

        requirement_clarity_score: clarityScore,

        timeline_score: timelineScore,

        business_fit_score: businessFitScore,

        service_fit_score: serviceFitScore,

        decision_maker_score: decisionMakerScore,

        total_score: totalScore,

        classification: classification

      }

    }

  });

}

return results;
